const text = (v) => (typeof v === 'string' ? v : '');
const articles = $('RSS Feed Trigger').all();
return articles.map((it, i) => {
  const a = it.json;
  const link = text(a.link);
  // article-<brand>-<hash of the guid or link>: stable, 105 characters at most, and different for each brand.
  const ref = text(a.guid) || link || text(a.isoDate) || text(a.title) || 'item-' + i;
  const eventId = 'article-' + slug + '-' + sha256Hex(ref).slice(0, 32);
  return {
    json: {
      workflow,
      brand: slug,
      event_id: eventId,
      title: String(a.title || '').slice(0, 120),
      article_url: link.slice(0, 300),
      url: api + '/generation-requests',
      runsUrl: api + '/runs',
      body: {
